"""SQLite persistence layer for RetoBox.

Uses the Python standard-library ``sqlite3`` driver directly to keep the
dependency surface minimal. A single connection is shared across the app with
``check_same_thread=False``; FastAPI's default threadpool serializes through a
module-level lock to keep writes consistent on SQLite.

Ownership model
---------------
Every piece of per-player state is scoped by an ``owner_key``:

* ``u:<account_id>`` for logged-in accounts.
* ``g:<guest_key>``  for anonymous visitors (key generated by the browser).

Players (``users``), word groups and the draw state (``draw_state``) belong to
an owner. Collections belong to an account (``owner_id``) or are public presets
(``owner_id IS NULL``), which are read-only and shared by everyone.
"""

import json
import os
import sqlite3
import threading
from contextlib import contextmanager

# Database location is configurable via env var (default matches the contract).
DATABASE_PATH = os.environ.get("DATABASE_PATH", "/data/retobox.db")

# Bumped whenever the schema changes incompatibly. Databases created by an older
# RetoBox (before accounts existed) have no ``schema_meta`` table and are
# rejected at startup with an explicit message instead of being silently
# migrated: the old data was global and cannot be attributed to any owner.
SCHEMA_VERSION = 2

# A coarse lock guarding all DB access. SQLite handles modest concurrency
# poorly under threads; serializing is simple, correct, and more than fast
# enough for this workload.
_lock = threading.Lock()
_connection: sqlite3.Connection | None = None


class IncompatibleDatabaseError(RuntimeError):
    """Raised when the DB file predates the accounts schema."""


@contextmanager
def write_transaction():
    """Hold the DB lock for a multi-statement write; roll back if it fails.

    The connection is shared, so a partial write left in the implicit
    transaction would otherwise be committed by the next request's commit.
    """
    conn = get_connection()
    with _lock:
        try:
            yield conn
        except BaseException:
            conn.rollback()
            raise


def _ensure_parent_dir(path: str) -> None:
    parent = os.path.dirname(path)
    if parent and not os.path.exists(parent):
        os.makedirs(parent, exist_ok=True)


def get_connection() -> sqlite3.Connection:
    """Return the shared SQLite connection, creating it on first use."""
    global _connection
    if _connection is None:
        _ensure_parent_dir(DATABASE_PATH)
        _connection = sqlite3.connect(DATABASE_PATH, check_same_thread=False)
        _connection.row_factory = sqlite3.Row
        _connection.execute("PRAGMA journal_mode=WAL;")
        _connection.execute("PRAGMA foreign_keys=ON;")
    return _connection


def _table_exists(conn: sqlite3.Connection, name: str) -> bool:
    row = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?", (name,)
    ).fetchone()
    return row is not None


def init_db() -> None:
    """Create the schema if it does not exist.

    Refuses to start on a database created by a pre-accounts RetoBox (tables
    present but no ``schema_meta``): remove the old volume/file and start
    again. This is safe to run on every startup against a live DB.
    """
    conn = get_connection()
    with _lock:
        if _table_exists(conn, "challenges") and not _table_exists(conn, "schema_meta"):
            raise IncompatibleDatabaseError(
                f"Database at {DATABASE_PATH} predates the accounts schema. "
                "Back it up and delete it (or the Docker volume) before starting."
            )
        conn.executescript(
            """
            CREATE TABLE IF NOT EXISTS schema_meta (
                version INTEGER NOT NULL
            );

            -- Cuentas registradas (email+contraseña y/o Google).
            CREATE TABLE IF NOT EXISTS accounts (
                id            INTEGER PRIMARY KEY AUTOINCREMENT,
                email         TEXT    NOT NULL UNIQUE,
                name          TEXT    NOT NULL,
                password_hash TEXT,
                google_sub    TEXT    UNIQUE,
                created_at    TEXT    NOT NULL
            );

            -- Sesiones (token opaco en cookie; aquí solo se guarda su hash).
            CREATE TABLE IF NOT EXISTS sessions (
                token_hash TEXT    PRIMARY KEY,
                account_id INTEGER NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
                created_at TEXT    NOT NULL,
                expires_at TEXT    NOT NULL
            );

            -- Colecciones: owner_id NULL = preset pública (solo lectura).
            CREATE TABLE IF NOT EXISTS collections (
                id         INTEGER PRIMARY KEY AUTOINCREMENT,
                name       TEXT    NOT NULL,
                owner_id   INTEGER REFERENCES accounts(id) ON DELETE CASCADE,
                preset_key TEXT    UNIQUE,
                created_at TEXT    NOT NULL
            );

            CREATE TABLE IF NOT EXISTS challenges (
                id             INTEGER PRIMARY KEY AUTOINCREMENT,
                title          TEXT    NOT NULL,
                description    TEXT    NOT NULL DEFAULT '',
                required_users INTEGER NOT NULL DEFAULT 1,
                involved_users INTEGER,
                repeatable     INTEGER NOT NULL DEFAULT 0,
                created_at     TEXT    NOT NULL,
                collection_id  INTEGER NOT NULL REFERENCES collections(id) ON DELETE CASCADE
            );

            -- Estado de la sesión de juego por dueño: veces que le ha salido
            -- cada carta. is_used se deriva (draw_count > 0 y no repetible).
            CREATE TABLE IF NOT EXISTS draw_state (
                owner_key    TEXT    NOT NULL,
                challenge_id INTEGER NOT NULL REFERENCES challenges(id) ON DELETE CASCADE,
                draw_count   INTEGER NOT NULL DEFAULT 0,
                PRIMARY KEY (owner_key, challenge_id)
            );

            -- Jugadores (avatares de color) de cada dueño.
            CREATE TABLE IF NOT EXISTS users (
                id        INTEGER PRIMARY KEY AUTOINCREMENT,
                owner_key TEXT NOT NULL,
                name      TEXT NOT NULL,
                color     TEXT NOT NULL
            );

            -- Grupos de palabras del mezclador. owner_key NULL = preset pública.
            -- Las palabras se guardan como un array JSON en una sola columna.
            CREATE TABLE IF NOT EXISTS word_groups (
                id         INTEGER PRIMARY KEY AUTOINCREMENT,
                owner_key  TEXT,
                preset_key TEXT    UNIQUE,
                name       TEXT    NOT NULL,
                words      TEXT    NOT NULL DEFAULT '[]',
                created_at TEXT    NOT NULL
            );

            CREATE INDEX IF NOT EXISTS idx_challenges_collection
                ON challenges(collection_id);
            CREATE INDEX IF NOT EXISTS idx_collections_owner
                ON collections(owner_id);
            CREATE INDEX IF NOT EXISTS idx_users_owner
                ON users(owner_key);
            CREATE INDEX IF NOT EXISTS idx_word_groups_owner
                ON word_groups(owner_key);
            CREATE INDEX IF NOT EXISTS idx_sessions_account
                ON sessions(account_id);
            """
        )
        if conn.execute("SELECT 1 FROM schema_meta").fetchone() is None:
            conn.execute(
                "INSERT INTO schema_meta (version) VALUES (?)", (SCHEMA_VERSION,)
            )
        conn.commit()


# ---------------------------------------------------------------------------
# Row -> dict helpers (normalize SQLite's integer booleans)
# ---------------------------------------------------------------------------

def challenge_row_to_dict(row: sqlite3.Row) -> dict:
    """Serialize a challenge. ``row`` must include ``draw_count`` (the caller's
    own draw state, 0 when the card has not been drawn by them)."""
    repeatable = bool(row["repeatable"])
    draw_count = row["draw_count"] or 0
    return {
        "id": row["id"],
        "title": row["title"],
        "description": row["description"],
        "required_users": row["required_users"],
        "involved_users": row["involved_users"],
        "repeatable": repeatable,
        "is_used": (not repeatable) and draw_count > 0,
        "created_at": row["created_at"],
        "collection_id": row["collection_id"],
    }


def collection_row_to_dict(row: sqlite3.Row) -> dict:
    return {
        "id": row["id"],
        "name": row["name"],
        "owner_id": row["owner_id"],
        "preset": row["owner_id"] is None,
        "created_at": row["created_at"],
    }


def user_row_to_dict(row: sqlite3.Row) -> dict:
    return {
        "id": row["id"],
        "name": row["name"],
        "color": row["color"],
    }


def word_group_row_to_dict(row: sqlite3.Row) -> dict:
    try:
        words = json.loads(row["words"]) if row["words"] else []
    except (ValueError, TypeError):
        words = []
    return {
        "id": row["id"],
        "name": row["name"],
        "words": [w for w in words if isinstance(w, str)],
        "preset": row["owner_key"] is None,
        "created_at": row["created_at"],
    }


def account_row_to_dict(row: sqlite3.Row) -> dict:
    return {
        "id": row["id"],
        "email": row["email"],
        "name": row["name"],
        "has_password": row["password_hash"] is not None,
        "has_google": row["google_sub"] is not None,
    }
